-- 1483: второй абзац описания четырёх парков — о природе территории
-- (пачка 4 тонких страниц, 21.11). Первый абзац — сверенный справочник
-- (1243–1250: площадь, статус, разрешения) — не меняется: новый абзац
-- дописывается через перевод строки, страница парка рисует абзацы отдельно.
-- Тексты переписаны по статьям Википедии (источники — в тесте 1483), без
-- цен и сезонов; числа сверены с источником и с первым абзацем.
-- «Река Коль» и «Вилючинский» не дополнялись: доступные источники не дают
-- фактов сверх уже записанных (документы парка с сервера не открылись).
-- Повторный прогон ничего не меняет: абзац дописывается, только если его ещё нет.

WITH src(slug, txt) AS (VALUES
  ('bystrinskiy',
   'Парк лежит на Срединном, Козыревском и Быстринском хребтах и захватывает часть Центрально-Камчатской депрессии; с севера на юг он тянется на 142 км, с востока на запад — на 118 км. Кроме Эссо и Анавгая здесь есть сезонный посёлок Горный Ключ, заказник «Ичинский» и памятники природы «Лиственничник багульниковый» и «Апапельская каменная баба». Лето короткое и жаркое, зима безветренная и морозная: в январе в среднем −19 °C, в июле 12–14 °C. Групп термальных источников пять — Апапельско-Оксинская, Анавгайская, Быстринская, Эссовская и Козыревская; Апапельско-Оксинские — кипящие термы с температурой у выхода около 100 °C. Во флоре парка 674 вида сосудистых растений, 142 вида печёночников и 313 видов мхов.'),
  ('klyuchevskoy',
   'Ключевская группа — крупнейшая группа вулканов России: она занимает 6,5 тыс. км² в нижнем течении реки Камчатки, там, где река поворачивает на восток, на стыке Курило-Камчатского и Алеутского вулканических поясов. Её возраст учёные оценивают в несколько сотен тысяч лет. Действующие вулканы группы — Ключевской, Безымянный, Плоский Толбачик и Дальний Плоский; потухшие — Камень, Ближний Плоский, Средний, Острый Толбачик, Острая и Овальная Зимины, Горный Зуб, Большая и Малая Удины.'),
  ('komandorskiy',
   'Парк носит имя С. В. Маракова и вырос из заповедника «Командорский», созданного в 1993 году. Кроме четырёх крупных островов в него входят более 60 мелких островков; общая площадь — 3 648 679 гектаров, из них 3 463 300 — морская акватория. Высшая точка — гора Стеллера, 755 м. Острова — западные вершины подводного вулканического хребта, который тянется от Аляски к Камчатке. В водах парка отмечено 250 видов рыб и 21 вид китообразных, в списке птиц — 213 видов, а вдоль берегов держится около 300 тысяч морских зверей. На острове Беринга сохранилась стоянка экспедиции Витуса Беринга 1741–1742 годов с могилой мореплавателя.'),
  ('vachkazhets',
   'Высшая точка массива — гора Вачкажец, 1556 м; рядом стоят гора Вачкажицы (1502 м) и Летняя Поперечная (1417 м). Вачкажец долго считали древним вулканом, разрушенным извержением, но спор о его происхождении закончился в XXI веке в пользу тектонического поднятия. В последнее оледенение, 60–10 тысяч лет назад, здесь лежал ледник площадью около 120 км² и толщиной до 150 м, спускавшийся до высоты 200 м. Ледник растаял, а оставленные им кары, цирки и троговые долины стали главными достопримечательностями массива вместе с водопадами и озером Тахколоч, которое подпирает древний моренный вал.')
)
UPDATE parks p
   SET description = btrim(p.description) || E'\n' || src.txt,
       updated_at = NOW()
  FROM src
 WHERE p.slug = src.slug
   AND p.description IS NOT NULL
   AND char_length(btrim(p.description)) > 0
   AND position(src.txt IN p.description) = 0;
